import React from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faShoppingCart } from '@fortawesome/free-solid-svg-icons';
import './ZapatosCard.css';

const ZapatosCard = ({key,
  id, 
  marca,
  costo,
  color,
  modelo,
  calidad,
  descripcion,
  url,
  talla}) => {

  return (
    <div className="zapatos-card" title={id}>
      <img
        src={url}
        alt="Zapato"
        className="zapatos-image"
      />
      <div className="zapatos-info">

        <div className='titulo-zapato'><p className="zapatos-name">Marca:{marca}</p></div>
        
       
        <div className='display-flex-cards'>
              <div className="zapatos-price">${costo}</div>
              <div className="zapatos-price"> - {calidad} - </div>
              <div className="zapatos-price"> {modelo}</div>
        </div>
        <div className="dropdown">
            <div className="dropdown-content">
             Talla: {talla}
              - Color: {color}
              </div>
        </div>
       { /*<p className="zapatos-description">Descripción: {descripcion}</p>*/}
        <button className="zapatos-btn" >
            <FontAwesomeIcon icon={faShoppingCart} className="cart-icon" />
            Agregar al carrito
          </button>
      </div>
    </div>
  );
}

export default ZapatosCard;
